{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Gathering Events — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfaf8;--accent:#6c4bd1;--muted:#6b6b6b;--card:#fff;--glass:rgba(255,255,255,0.6);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#f4f3f8) no-repeat fixed;padding:0;color:#222}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:48px;height:48px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#8e5efc);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-size:15px}
    .hero{max-width:960px;margin:18px auto;padding:28px;border-radius:14px;background:linear-gradient(180deg,rgba(108,75,209,0.06),rgba(140,114,255,0.03));box-shadow:0 8px 30px rgba(40,30,80,0.06);position:relative}
    .hero h1{margin:0 0 10px 0;font-size:28px;color:#171725}
    .hero p{margin:0 0 18px 0;color:var(--muted)}
    .cta{display:inline-block;background:var(--accent);color:white;padding:10px 16px;border-radius:10px;text-decoration:none}
    .layout{display:grid;grid-template-columns:1fr 360px;gap:20px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 4px 18px rgba(36,30,65,0.06)}
    .next-event{border-left:4px solid var(--accent);padding-left:14px}

    .mixer{display:flex;gap:10px;align-items:center}
    .mixer button{padding:8px 12px;border-radius:8px;border:1px solid #eee;background:#fff;cursor:pointer}
    .mixer button.active{background:linear-gradient(90deg,var(--accent),#8e5efc);color:white;border:none}

    .programs li{margin:10px 0;padding:12px;border-radius:8px;background:linear-gradient(180deg,#fff,#fbfbff);list-style:none}
    .calendar{margin-top:10px}
    .calendar time{display:block;font-weight:600}
    .badge-row{display:flex;gap:10px;align-items:center;margin-top:12px}
    .badge{width:44px;height:44px;border-radius:8px;background:#f2f2ff;display:inline-flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent);position:relative;cursor:default}
    .badge[data-tooltip]{position:relative}
    .badge[data-tooltip]:hover::after{content:attr(data-tooltip);position:absolute;top:-38px;left:50%;transform:translateX(-50%);white-space:nowrap;background:#222;color:#fff;padding:6px 8px;border-radius:6px;font-size:12px}

    .testimonials{margin-top:18px}
    .testimonial{min-height:72px;display:flex;flex-direction:column;justify-content:center}

    footer{margin-top:24px;padding:18px;text-align:center;color:var(--muted);font-size:13px}

    /* subtle patterned background using local svg */
    body::before{content:"";position:fixed;inset:0;background-image:url('assets/img/pattern.svg');opacity:0.06;pointer-events:none}

    @media (max-width:880px){.layout{grid-template-columns:1fr}.hero{margin:12px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Gather</a>
      <a href="events.html">Sessions</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">About</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html" style="background:#111;color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main class="hero">
    <h1>Group sound evenings tuned to steady down and open up</h1>
    <p>Join a guided session that layers tuned bowls, breath cues, and gentle movement to shift restless systems into simple ease. Choose a listening level below to see suggested events.</p>
    <a class="cta" href="book.html">Reserve a seat</a>

    <div class="layout" style="margin-top:22px">
      <section>
        <div class="card next-event">
          <h3 style="margin:0 0 8px 0">Next event</h3>
          <div id="nextEventBlock">
            <time datetime="2026-03-05T19:00">Fri, Mar 5 • 7:00–8:15 PM</time>
            <div style="color:var(--muted);margin-top:8px">Community round — gentle waves of harmonic bowls and vocal layers</div>
            <div style="margin-top:12px"><a class="cta" href="book.html">Claim a space</a></div>
          </div>
          <div style="margin-top:12px;color:var(--muted);font-size:13px">Location: {{CITY}}, {{STATE}} • Bring a blanket and water</div>
        </div>

        <div class="card" style="margin-top:14px">
          <h4 style="margin:0 0 8px 0">Choose how you want to land</h4>
          <div class="mixer" role="tablist" aria-label="Sound intensity">
            <button id="mixGentle" class="active" data-level="gentle">Gentle</button>
            <button id="mixMedium" data-level="medium">Medium</button>
            <button id="mixIntense" data-level="intense">Intense</button>
          </div>

          <ul class="programs" id="programList" style="margin-top:12px;padding:0">
            <!-- program recommendations populated by JS -->
          </ul>
        </div>

        <div class="card calendar" aria-live="polite" style="margin-top:14px">
          <h4 style="margin:0 0 10px 0">Upcoming schedule</h4>
          <div id="calendarList">
            <!-- calendar items populated by JS -->
          </div>
        </div>

      </section>

      <aside>
        <div class="card">
          <h4 style="margin:0 0 8px 0">Proof and presence</h4>
          <div class="badge-row">
            <div class="badge" data-tooltip="Featured in The Local Wellness Journal">LW</div>
            <div class="badge" data-tooltip="Partner studio: Solstice Rooms">SR</div>
            <div class="badge" data-tooltip="Endorsed by local therapists">HT</div>
          </div>

          <div class="testimonials" id="testimonialArea" style="margin-top:12px">
            <!-- rotating testimonial injected by JS -->
            <div class="testimonial">Loading reflections...</div>
          </div>

          <div style="margin-top:12px;color:var(--muted);font-size:13px">A rotating selection of attendee notes and third-party recognitions. Hover a badge to learn more.</div>
        </div>

        <div class="card" style="margin-top:14px">
          <h4 style="margin:0 0 8px 0">Safety & suitability</h4>
          <div style="color:var(--muted);font-size:13px">Contraindications: If you are pregnant, have uncontrolled epilepsy, severe psychiatric conditions, or use a pacemaker/implanted device, consult a clinician before attending. If you feel uncomfortable with vibration or extended lying, we can adapt the session. Contact {{EMAIL}} for specific questions.</div>
        </div>

      </aside>
    </div>

    <div style="margin-top:18px;display:flex;gap:10px;align-items:center">
      <a class="cta" href="book.html">Book a seat</a>
      <a href="private-sessions.html" style="padding:10px 12px;border-radius:8px;text-decoration:none;border:1px solid #e6e6ee;color:var(--accent)">Explore private options</a>
    </div>

  </main>

  <footer>
    <div>Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <script>
    (function(){
      // DATA
      const events = [
        {date:'2026-03-05T19:00',label:'Community round — harmonic bowls',level:'gentle'},
        {date:'2026-03-12T19:30',label:'Deep Tones — layered gong textures',level:'intense'},
        {date:'2026-03-19T18:00',label:'Midweek Reset — voice and chimes',level:'medium'},
        {date:'2026-03-26T19:00',label:'Slow Evening — bowls and breath',level:'gentle'}
      ];

      const programsByLevel = {
        gentle:[
          {title:'Restful Waves',desc:'A softer pool of bowls and vocal harmonics for settling into sleep-like calm.'},
          {title:'Near‑Silent Drift',desc:'Low-volume tones, staggered breath guidance, ideal for newcomers.'}
        ],
        medium:[
          {title:'Layered Relief',desc:'Steady rhythmic frames with medium sustain for clearer mental spacing.'},
          {title:'Vocal Loom',desc:'Combined bowls and gentle vocal layers to invite deeper attention.'}
        ],
        intense:[
          {title:'Deep Resonance Field',desc:'Long-form gong and low bowls for tactile vibration and sustained release.'},
          {title:'Intensive Wave',desc:'Extended tonal clusters for folks seeking a pronounced shift.'}
        ]
      };

      const testimonials = [
        {text:'The session loosened a persistent knot of anxiety — I slept deeper than I have in months.',author:'— Maya, attendee'},
        {text:'I appreciated the clear cues and how the room was arranged to feel safe and unrushed.',author:'— Carlos, educator'},
        {text:'An approachable experience that surprised me with how rested I felt the next day.',author:'— Priya, nurse'}
      ];

      // UI refs
      const mixButtons = document.querySelectorAll('.mixer button');
      const programList = document.getElementById('programList');
      const calendarList = document.getElementById('calendarList');
      const testimonialArea = document.getElementById('testimonialArea');

      function renderPrograms(level){
        programList.innerHTML='';
        (programsByLevel[level]||[]).forEach(p=>{
          const li=document.createElement('li');
          li.innerHTML=`<strong>${p.title}</strong><div style=\"color:var(--muted);font-size:13px;margin-top:6px\">${p.desc}</div>`;
          programList.appendChild(li);
        });
      }

      function renderCalendar(){
        calendarList.innerHTML='';
        events.forEach(ev=>{
          const d=new Date(ev.date);
          const el=document.createElement('div');
          el.style.padding='8px 0';
          el.innerHTML=`<time datetime=\"${ev.date}\">${d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})} • ${d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</time><div style=\"color:var(--muted);font-size:13px;margin-top:4px\">${ev.label} <span style=\"color:#999\">• ${ev.level}</span></div>`;
          calendarList.appendChild(el);
        });
      }

      // mixer control
      mixButtons.forEach(b=>{
        b.addEventListener('click',()=>{
          mixButtons.forEach(x=>x.classList.remove('active'));
          b.classList.add('active');
          renderPrograms(b.dataset.level);
        });
      });

      // testimonials rotation
      let tIndex=0;
      function showTestimonial(i){
        const t=testimonials[i];
        testimonialArea.innerHTML=`<div class=\"testimonial\"><div style=\"font-style:italic\">\"${t.text}\"</div><div style=\"margin-top:8px;font-weight:700;color:var(--muted);font-size:13px\">${t.author}</div></div>`;
      }
      showTestimonial(0);
      setInterval(()=>{ tIndex=(tIndex+1)%testimonials.length; showTestimonial(tIndex); },5200);

      // initial render
      renderPrograms('gentle');
      renderCalendar();

      // Next-event dynamic: if the next event changes, update the block
      const nextEv = events[0];
      const nextBlock = document.getElementById('nextEventBlock');
      nextBlock.setAttribute('aria-live','polite');

    })();
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Private Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--accent:#1565d8;--muted:#5b5b66;--card:#fff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#fbfdff,#f7f9ff)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 24px}
    .brand{display:flex;gap:12px;align-items:center}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}

    .container{max-width:980px;margin:18px auto;padding:18px}
    .hero{display:flex;gap:18px;align-items:flex-start}
    .hero .left{flex:1}
    .card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 6px 24px rgba(22,26,40,0.06)}
    .session-options{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}
    .option{padding:12px;border-radius:10px;border:1px solid #eef2ff}
    .mixer-vertical{display:flex;gap:8px;flex-direction:column;margin-top:10px}
    .mixer-vertical button{padding:8px;border-radius:8px;border:none;background:#f7f8ff;cursor:pointer}
    .mixer-vertical button.active{background:var(--accent);color:white}

    .note{color:var(--muted);font-size:13px;margin-top:8px}
    .cta{display:inline-block;background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none}

    .aside{width:320px}
    .price-box{font-size:24px;font-weight:700;color:#222}

    @media (max-width:900px){.hero{flex-direction:column}.aside{width:100%}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div style="width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#5b9dff);display:flex;align-items:center;justify-content:center;color:white;font-weight:700">PS</div>
      <div>
        <div style="font-weight:700">Private Sessions</div>
        <div style="font-size:12px;color:var(--muted)">One-to-one and small-group tailoring</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Gather</a>
      <a href="events.html">Sessions</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Rates</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main class="container">
    <div class="hero">
      <div class="left">
        <div class="card">
          <h2 style="margin:0 0 8px 0">Personal sound work for targeted rest</h2>
          <p class="note">Sessions are crafted around your nervous system, goals, and comfort. Choose an intensity to see how a private session might be arranged.</p>

          <div style="margin-top:12px">Intensity chooser</div>
          <div class="mixer-vertical" role="tablist" aria-label="Private intensity">
            <button id="pGentle" class="active" data-level="gentle">Soft — grounding & stable</button>
            <button id="pMedium" data-level="medium">Balanced — deeper layers</button>
            <button id="pIntense" data-level="intense">Deep — resonance & release</button>
          </div>

          <div id="privatePlan" style="margin-top:14px"></div>

          <div style="margin-top:14px">
            <a class="cta" href="book.html">Request a private session</a>
            <a href="contact.html" style="margin-left:10px;color:var(--muted);text-decoration:none">Ask a question</a>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin:0 0 8px 0">How a private session differs</h4>
          <ul style="margin:0;padding-left:18px;color:var(--muted)">
            <li>Time and instrumentation tailored to your sensitivity</li>
            <li>Short intake to set intention and check medical suitability</li>
            <li>Flexible positioning: seated, semi-reclined, or lying</li>
          </ul>
          <div class="note">Contraindications: Private sessions may still be unsuitable for those with implanted electronic medical devices, recent cranial surgery, or uncontrolled seizures. Always check with your clinician if unsure.</div>
        </div>

      </div>

      <aside class="aside">
        <div class="card">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div style="font-size:13px;color:var(--muted)">Estimated single-session range</div>
              <div class="price-box" id="priceEstimate">—</div>
            </div>
            <div style="font-size:12px;color:var(--muted)">45–90 min</div>
          </div>

          <div style="margin-top:12px;color:var(--muted);font-size:13px">After you request, we’ll follow with a short intake and finalize the format for your needs. Multiple sessions can be packaged for ongoing support.</div>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin:0 0 8px 0">Small-group private options</h4>
          <div style="color:var(--muted);font-size:13px">Invite up to 6 people for a tailored evening. We design the flow to match your group intention — gentle winding down or a focused reset.</div>
        </div>

      </aside>
    </div>

    <div style="margin-top:12px;display:flex;gap:12px">
      <div class="card" style="flex:1">
        <h4 style="margin:0 0 8px 0">Attendee notes</h4>
        <div id="privateTestimonials" style="color:var(--muted);font-size:14px">Clients report improved sleep and clearer emotional boundaries after a short series.</div>
      </div>

      <div class="card" style="width:260px">
        <h4 style="margin:0 0 8px 0">Book or inquire</h4>
        <div style="display:flex;flex-direction:column;gap:8px">
          <a class="cta" href="book.html">Start a request</a>
          <a href="mailto:{{EMAIL}}" style="text-decoration:none;color:var(--muted);padding:8px 10px;border-radius:8px;border:1px solid #eef2ff;display:inline-block">Email us</a>
        </div>
      </div>
    </div>

  </main>

  <script>
    (function(){
      const plans = {
        gentle:{summary:'A calm, low-volume session with bowls and soft vocal harmonics. Intake and 45–60 minutes of guided sound.',price:'$95–$140'},
        medium:{summary:'Medium sustain and layered textures for a clear nervous-system reset. 60–75 minutes with customized tools.',price:'$140–$210'},
        intense:{summary:'Extended resonance work using low-frequency bowls and gong elements for deep release. 75–90 minutes.',price:'$210–$320'}
      };

      const buttons = document.querySelectorAll('.mixer-vertical button');
      const planBox = document.getElementById('privatePlan');
      const priceEstimate = document.getElementById('priceEstimate');

      function setPlan(level){
        buttons.forEach(b=>b.classList.toggle('active',b.dataset.level===level));
        const p = plans[level];
        planBox.innerHTML = `<div style=\"font-weight:700;margin-bottom:8px\">${p.summary}</div><div style=\"color:var(--muted);font-size:13px\">Recommended instruments: ${level==='gentle'?'soft bowls, chimes':level==='medium'?'bowls, voice, frame drum':'large bowls, gong, tuned earth tones'}</div>`;
        priceEstimate.textContent = p.price;
      }

      buttons.forEach(b=>b.addEventListener('click',()=>setPlan(b.dataset.level)));
      // init
      setPlan('gentle');
    })();
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Rates & Options — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7fbff;--accent:#1b9aa8;--muted:#64666e}
    body{margin:0;font-family:Inter,system-ui,Roboto,Arial;background:var(--bg);color:#111}
    .wrap{max-width:980px;margin:18px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    h1{margin:12px 0 6px 0}
    .tiers{display:flex;gap:12px;margin-top:14px}
    .tier{flex:1;background:white;padding:14px;border-radius:12px;box-shadow:0 10px 24px rgba(22,26,60,0.05)}
    .tier h3{margin:0}
    .price{font-size:22px;font-weight:800;margin-top:12px}
    .features{color:var(--muted);margin-top:10px}
    .mixer-inline{display:flex;gap:8px;align-items:center;margin-top:12px}
    .mixer-inline button{padding:8px 12px;border-radius:8px;border:none;background:#eef9fb;cursor:pointer}
    .mixer-inline button.active{background:var(--accent);color:white}
    .cta{display:inline-block;margin-top:12px;background:var(--accent);color:white;padding:10px 12px;border-radius:10px;text-decoration:none}
    .disclaimer{margin-top:14px;color:var(--muted);font-size:13px}

    @media (max-width:880px){.tiers{flex-direction:column}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
      <nav>
        <a href="index.html">Gather</a>
        <a href="events.html">Sessions</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Rates</a>
        <a href="book.html">Book</a>
      </nav>
    </header>

    <h1>Flexible pricing shaped around intent</h1>
    <p style="color:var(--muted)">We price by session style rather than a single number so you can choose the format that fits your needs. Pick an empathy level to see typical ranges.</p>

    <div class="mixer-inline">
      <div style="font-weight:600;color:var(--muted)">Choose listening intensity:</div>
      <button id="rGentle" class="active" data-level="gentle">Gentle</button>
      <button id="rMedium" data-level="medium">Balanced</button>
      <button id="rIntense" data-level="intense">Deep</button>
    </div>

    <div class="tiers" id="tiersArea">
      <div class="tier" data-type="community">
        <h3>Community Seat</h3>
        <div class="price" id="priceCommunity">—</div>
        <div class="features">Shared room, guided cues, 60–75 minutes. Best for exploratory rest.</div>
        <a class="cta" href="book.html">Reserve community</a>
      </div>

      <div class="tier" data-type="private">
        <h3>Private Session</h3>
        <div class="price" id="pricePrivate">—</div>
        <div class="features">One-to-one tailoring, intake, 45–90 minutes depending on depth.</div>
        <a class="cta" href="private-sessions.html">Request private</a>
      </div>

      <div class="tier" data-type="series">
        <h3>Focused Series</h3>
        <div class="price" id="priceSeries">—</div>
        <div class="features">3 or 6-session packages for sustained benefit and integration.</div>
        <a class="cta" href="book.html">Start a series</a>
      </div>
    </div>

    <div class="disclaimer">
      Contraindications: Persons with pacemakers or implanted electronics, recent cranial surgery, or uncontrolled seizures should consult a medical professional before participating. If pregnant or under psychiatric care, please connect with us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> to discuss adaptations.
    </div>

    <footer style="margin-top:20px;color:var(--muted)">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or visit our <a href="faq.html">FAQ</a>.</footer>
  </div>

  <script>
    (function(){
      const bracket = {
        gentle:{community:'$22–$28',private:'$95–$140',series:'$250–$420'},
        medium:{community:'$26–$34',private:'$140–$210',series:'$360–$580'},
        intense:{community:'$30–$40',private:'$210–$320',series:'$540–$820'}
      };

      const buttons = document.querySelectorAll('.mixer-inline button');
      const pc = document.getElementById('priceCommunity');
      const pp = document.getElementById('pricePrivate');
      const ps = document.getElementById('priceSeries');

      function setRates(level){
        buttons.forEach(b=>b.classList.toggle('active',b.dataset.level===level));
        const data = bracket[level];
        pc.textContent = data.community;
        pp.textContent = data.private;
        ps.textContent = data.series;
      }

      buttons.forEach(b=>b.addEventListener('click',()=>setRates(b.dataset.level)));
      setRates('gentle');
    })();
  </script>
</body>
</html>"} 
